const REFERENCE_START = Date.UTC(2026, 0, 1);
const DAY_MS = 86_400_000;

export function getReferenceDayStarDetails(date: string): ReferenceDayStars | null {
  const match = date.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;
  const index = Math.floor((Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])) - REFERENCE_START) / DAY_MS);
  const row = REFERENCE_DAYS[index];
  if (!row) return null;
  const toDetails = (indices: number[]) => indices.map((starIndex) => ({ name: STAR_DETAILS[starIndex][0], description: STAR_DETAILS[starIndex][1] }));
  return { goodStars: toDetails(row[0]), badStars: toDetails(row[1]) };
}
